PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,name TEXT NOT NULL,timezone TEXT NOT NULL DEFAULT 'America/New_York',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS families(id TEXT PRIMARY KEY,name TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES users(id),settings TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('parent','student')),status TEXT NOT NULL DEFAULT 'active',UNIQUE(family_id,user_id,role));
CREATE TABLE IF NOT EXISTS chores(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id),creator_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,difficulty TEXT NOT NULL,points INTEGER NOT NULL,xp INTEGER NOT NULL,recurrence TEXT NOT NULL,requires_approval INTEGER NOT NULL,requires_proof INTEGER NOT NULL,archived_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assignments(id TEXT PRIMARY KEY,chore_id TEXT NOT NULL REFERENCES chores(id),student_id TEXT NOT NULL REFERENCES users(id),due_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('todo','pending','changes_requested','approved','rejected','completed')),awarded_submission_id TEXT,created_at TEXT NOT NULL,UNIQUE(chore_id,student_id,due_at));
CREATE INDEX IF NOT EXISTS assignment_queue ON assignments(student_id,status,due_at);
CREATE TABLE IF NOT EXISTS submissions(id TEXT PRIMARY KEY,assignment_id TEXT NOT NULL REFERENCES assignments(id),attempt INTEGER NOT NULL,note TEXT NOT NULL,proof_url TEXT,status TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(assignment_id,attempt));
CREATE TABLE IF NOT EXISTS decisions(id TEXT PRIMARY KEY,submission_id TEXT NOT NULL REFERENCES submissions(id),parent_id TEXT NOT NULL REFERENCES users(id),decision TEXT NOT NULL,note TEXT NOT NULL,reversed_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS point_transactions(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id),student_id TEXT NOT NULL REFERENCES users(id),amount INTEGER NOT NULL,kind TEXT NOT NULL,note TEXT NOT NULL,reference_id TEXT,idempotency_key TEXT UNIQUE NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS point_ledger ON point_transactions(student_id,created_at);
CREATE TABLE IF NOT EXISTS xp_transactions(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id),student_id TEXT NOT NULL REFERENCES users(id),amount INTEGER NOT NULL,kind TEXT NOT NULL,reference_id TEXT,idempotency_key TEXT UNIQUE NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS daily_activity(id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES users(id),local_date TEXT NOT NULL,timezone TEXT NOT NULL,qualifying_count INTEGER NOT NULL,UNIQUE(student_id,local_date));
CREATE TABLE IF NOT EXISTS rewards(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id),name TEXT NOT NULL,description TEXT NOT NULL,icon TEXT NOT NULL,cost INTEGER NOT NULL,stock INTEGER NOT NULL,enabled INTEGER NOT NULL,requires_approval INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reward_goals(id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES users(id),reward_id TEXT NOT NULL REFERENCES rewards(id),active INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS redemptions(id TEXT PRIMARY KEY,reward_id TEXT NOT NULL REFERENCES rewards(id),student_id TEXT NOT NULL REFERENCES users(id),cost INTEGER NOT NULL,status TEXT NOT NULL,idempotency_key TEXT UNIQUE NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,body TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activity_logs(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id),actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,message TEXT NOT NULL,amount INTEGER,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS preferences(user_id TEXT PRIMARY KEY REFERENCES users(id),theme TEXT NOT NULL DEFAULT 'garden',animation INTEGER NOT NULL DEFAULT 1,reduced_motion INTEGER NOT NULL DEFAULT 0,sound INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS achievements(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,icon TEXT NOT NULL,threshold INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_achievements(user_id TEXT NOT NULL REFERENCES users(id),achievement_id TEXT NOT NULL REFERENCES achievements(id),earned_at TEXT NOT NULL,PRIMARY KEY(user_id,achievement_id));
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),token_hash TEXT UNIQUE NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
